export function normalizeOrder(input) {
  const errors = [];
  if (typeof input.customerId !== "string" || input.customerId.trim() === "") errors.push({ path: "customerId", code: "required" });
  if (!Array.isArray(input.lines)) errors.push({ path: "lines", code: "array_required" });
  const lines = Array.isArray(input.lines) ? input.lines : [];
  lines.forEach((line, index) => {
    if (typeof line.sku !== "string" || line.sku.trim() === "") errors.push({ path: `lines.${index}.sku`, code: "required" });
    if (!Number.isSafeInteger(line.quantity) || line.quantity <= 0) errors.push({ path: `lines.${index}.quantity`, code: "positive_integer_required" });
  });
  if (errors.length > 0) return { ok: false, errors };
  return { ok: true, value: { customerId: input.customerId.trim(), lines: lines.map((line) => ({ sku: line.sku.trim(), quantity: line.quantity })) } };
}
